head.b:skin:
:root { --navy:#0b1730; --navy2:#13294b; --gold:#d9ad52; --ink:#182235; --muted:#5c6678; --paper:#f5f7fb; --white:#fff; }
* { box-sizing:border-box; }
body { margin:0; background:var(--paper); color:var(--ink); font:16px/1.7 Arial, sans-serif; }
a { color:#173d70; text-decoration:none; }
a:hover { color:#9a6c13; }
.topbar { background:var(--navy); color:#fff; padding:8px 18px; text-align:center; font-size:13px; }
.site-header { background:linear-gradient(125deg,var(--navy),var(--navy2)); color:#fff; border-bottom:4px solid var(--gold); }
.wrap { width:min(1120px, calc(100% - 32px)); margin:0 auto; }
.brand-row { padding:27px 0 22px; }
.brand { margin:0; font-size:clamp(25px,4vw,38px); line-height:1.2; font-weight:800; letter-spacing:-.5px; }
.tagline { color:#e6eaf2; margin:8px 0 0; }
.nav { display:flex; flex-wrap:wrap; gap:7px; padding:0 0 17px; }
.nav a { color:#fff; padding:8px 12px; border:1px solid rgba(255,255,255,.16); border-radius:7px; font-size:14px; }
.nav a:hover { background:var(--gold); color:var(--navy); }
.hero { margin:28px auto; padding:clamp(24px,5vw,48px); border-radius:18px; background:linear-gradient(125deg,#fff,#eef2f8); border:1px solid #e0e6ef; box-shadow:0 10px 30px rgba(11,23,48,.06); }
.eyebrow { color:#946a18; text-transform:uppercase; font-size:12px; font-weight:800; letter-spacing:1.5px; }
.hero h2 { margin:8px 0 12px; color:var(--navy); font-size:clamp(26px,4vw,40px); line-height:1.2; }
.hero p { max-width:760px; color:var(--muted); }
.actions { display:flex; flex-wrap:wrap; gap:10px; margin-top:20px; }
.btn { display:inline-block; background:var(--navy); color:#fff; border-radius:8px; padding:11px 17px; font-weight:700; }
.btn.gold { background:var(--gold); color:var(--navy); }
.section-title { color:var(--navy); font-size:25px; margin:30px 0 14px; }
.cards { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:15px; margin-bottom:28px; }
.service-card { background:#fff; border:1px solid #e1e7f0; border-radius:13px; padding:20px; box-shadow:0 5px 16px rgba(11,23,48,.035); }
.service-card h3 { margin:0 0 7px; color:var(--navy); font-size:18px; }
.service-card p { margin:0; color:var(--muted); font-size:14px; }
.content-grid { display:grid; grid-template-columns:minmax(0,2fr) minmax(230px,1fr); gap:24px; align-items:start; margin-bottom:35px; }
.main-column, .sidebar-column { min-width:0; }
.widget, .post-outer, .Blog .blog-posts { background:#fff; border:1px solid #e1e7f0; border-radius:12px; padding:22px; margin-bottom:18px; }
.post-title, .post-title a { color:var(--navy); font-size:25px; line-height:1.3; }
.post-body img { max-width:100%; height:auto; }
.post-body { overflow-wrap:anywhere; }
.date-header, .post-footer, .post-timestamp { color:var(--muted); font-size:13px; }
.sidebar-column .widget h2 { color:var(--navy); font-size:18px; }
.site-footer { background:var(--navy); color:#e8edf5; margin-top:28px; padding:28px 0; }
.footer-links { display:flex; flex-wrap:wrap; gap:15px; }
.footer-links a { color:#f3d58e; }
.copyright { font-size:13px; color:#bfc9d9; margin-top:12px; }
.status-msg-wrap, .feed-links { display:none; }
@media (max-width:800px) { .cards { grid-template-columns:repeat(2,minmax(0,1fr)); } .content-grid { grid-template-columns:1fr; } }
@media (max-width:520px) { .wrap { width:min(100% - 22px,1120px); } .cards { grid-template-columns:1fr; } .nav { gap:6px; } .nav a { padding:7px 9px; font-size:13px; } .hero { margin:17px auto; } .widget, .post-outer, .Blog .blog-posts { padding:16px; } }
